import java.util.*;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.time.*;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import com.fasterxml.jackson.databind.ObjectMapper;
/** Uses Java 8 and the project's existing Jackson library. Environment variables contain test credentials. */
public class MerchantApiClientExample{
 static final ObjectMapper JSON=new ObjectMapper();
 public static String sign(String key,String time,String nonce,String path,String body)throws Exception{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(Base64.getDecoder().decode(key),"HmacSHA256"));byte[] bytes=m.doFinal((time+"\n"+nonce+"\n"+path+"\n"+body).getBytes(StandardCharsets.UTF_8));StringBuilder s=new StringBuilder();for(byte b:bytes)s.append(String.format("%02x",b&255));return s.toString();}
 public static String post(String base,String path,String merchant,String secret,Map<String,String> payload)throws Exception{String raw=JSON.writeValueAsString(payload),time=String.valueOf(Instant.now().getEpochSecond()),nonce=UUID.randomUUID().toString();HttpURLConnection c=(HttpURLConnection)new URL(base+path).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(5000);c.setReadTimeout(10000);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json;charset=UTF-8");c.setRequestProperty("X-Merchant-Id",merchant);c.setRequestProperty("X-Timestamp",time);c.setRequestProperty("X-Nonce",nonce);c.setRequestProperty("X-Signature",sign(secret,time,nonce,path,raw));try{try(OutputStream o=c.getOutputStream()){o.write(raw.getBytes(StandardCharsets.UTF_8));}InputStream stream=c.getResponseCode()<400?c.getInputStream():c.getErrorStream();ByteArrayOutputStream result=new ByteArrayOutputStream();if(stream!=null)try(InputStream in=stream){byte[] buffer=new byte[2048];int n;while((n=in.read(buffer))!=-1){if(result.size()+n>65536)throw new IOException("Response too large");result.write(buffer,0,n);}}String body=new String(result.toByteArray(),StandardCharsets.UTF_8);String signature=c.getHeaderField("X-Signature");if(signature!=null&&!java.security.MessageDigest.isEqual(signature.getBytes(StandardCharsets.US_ASCII),sign(secret,c.getHeaderField("X-Timestamp"),c.getHeaderField("X-Nonce"),path,body).getBytes(StandardCharsets.US_ASCII)))throw new IOException("Invalid response signature");return body;}finally{c.disconnect();}}
 public static void main(String[]args)throws Exception{String id=System.getenv("API_MERCHANT_ID"),secret=System.getenv("API_MERCHANT_SECRET"),number=System.getenv("API_CAMPUS_ORDER_NO");if(id==null||secret==null||number==null)throw new IllegalArgumentException("Set API_MERCHANT_ID, API_MERCHANT_SECRET and API_CAMPUS_ORDER_NO");Map<String,String> query=new LinkedHashMap<>();query.put("merchantId",id);query.put("campusOrderNo",number);System.out.println(post("http://127.0.0.1:8084","/api/v1/merchant/query",id,secret,query));}
}
